from typing import List

def periodic_orbit(p: int, q: int, base: int) -> List[int]:
    """Return remainders until the rational multiplicative orbit repeats."""
    if q <= 0 or base < 2:
        raise ValueError("invalid parameter")
    seen: dict[int, int] = {}
    orbit: List[int] = []
    remainder = p % q
    while remainder not in seen:
        seen[remainder] = len(orbit)
        orbit.append(remainder)
        remainder = (base * remainder) % q
    print(f"preperiod={seen[remainder]}, period={len(orbit)-seen[remainder]}")
    return orbit

if __name__ == "__main__":
    print(periodic_orbit(1, 97, 10))

